"""
Shared feature extraction for both detectors.

Both the rule-based and the ML detector score the same units - Modbus
*request* frames (the response direction is generated by the PLC, not by a
client, so it can't carry an attack) - and read them from the same capture
CSVs, so their comparison is apples-to-apples.

Provides:
  load_requests(csv)      -> tidy per-request DataFrame (typed, time-sorted,
                             with per-connection inter-arrival time)
  build_feature_matrix(df)-> numeric ndarray for the ML detector

Kept deliberately small and explicit: the exact columns the ML model sees are
easy to read off here, which matters for writing up the methodology.
"""

from __future__ import annotations

import sys

import numpy as np
import pandas as pd

# The numeric columns the ML anomaly detector is trained on. Chosen to match
# the proposal: function-code, register address/value, request size, and
# inter-packet timing per connection.
ML_FEATURE_COLUMNS = ["function_code", "address", "value0", "count", "inter_arrival"]

# The one-class SVM also sees the change in transaction ID from the previous
# request on the same connection. A normal master always adds 1; a verbatim
# replay repeats the old ID (change 0). The Isolation Forest is left on the
# five columns above: the change is constant in normal traffic, so a forest
# trained on it never splits on it (tested, no effect).
OCSVM_FEATURE_COLUMNS = ML_FEATURE_COLUMNS + ["txid_delta"]

# Value-change features (limitation 2: a replay whose transaction IDs are
# rewritten to look fresh). They describe a write against the process state
# it lands on, across ALL connections (the PLC has one state, whoever wrote it):
#   repeat_run - how many identical writes in a row this target has now
#                received (1 = a new value; reads 0). The operator nudges the
#                setpoint and toggles valves, so long runs of the same write
#                are rare; a replayed command repeated n times builds a run of n.
#   write_step - how far this write moves the target from the last value
#                written to it (0 for reads; NaN for the first write to a
#                target, filled by the detector with the training median).
OCSVM_CONTEXT_FEATURE_COLUMNS = OCSVM_FEATURE_COLUMNS + ["repeat_run", "write_step"]


READ_FCS = {1, 2, 3, 4}
WRITE_SINGLE_FCS = {5, 6}
WRITE_MULTI_FCS = {15, 16}


def _first_value(values_field: str) -> float:
    """First integer in the space-separated `values` column (0 for reads,
    which carry no written value). NaN if the field is present but is not a
    number, so the caller can count it instead of reading it as a real 0."""
    if isinstance(values_field, str) and values_field.strip():
        try:
            return float(values_field.split()[0])
        except (ValueError, IndexError):
            return float("nan")
    return 0.0


def _value_change(df: pd.DataFrame) -> tuple[list, list]:
    """repeat_run and write_step per request, in time order (see
    OCSVM_CONTEXT_FEATURE_COLUMNS). A target is a coil or a holding register
    at an address on one device (dst_ip when the capture has several, as on
    the GRFICSv2 plant); an FC16 block write counts as a write to its first
    register (value0)."""
    devices = df["dst_ip"] if "dst_ip" in df.columns else [""] * len(df)
    last: dict[tuple, tuple[float, int]] = {}   # target -> (last value, run length)
    runs, steps = [], []
    for fc, addr, value, dev in zip(df["function_code"], df["address"], df["value0"], devices):
        if fc not in WRITE_SINGLE_FCS | WRITE_MULTI_FCS:
            runs.append(0)
            steps.append(0.0)
            continue
        target = (str(dev), "coil" if fc in (5, 15) else "reg", int(addr))
        prev = last.get(target)
        if prev is None:
            run, step = 1, float("nan")
        else:
            run = prev[1] + 1 if value == prev[0] else 1
            step = abs(float(value) - prev[0])
        last[target] = (float(value), run)
        runs.append(run)
        steps.append(step)
    return runs, steps


def _malformed(df: pd.DataFrame, raw: dict) -> pd.Series:
    """True for a request the parser could not fully decode: a required field
    that was present but not a number, or a read/write whose address, count
    or value is missing (the tap leaves them blank when the PDU is too short
    to decode). Such a request used to become 'address 0, value 0', which can
    look exactly like a normal coil-OFF write."""
    bad = pd.Series(False, index=df.index)
    for col in ("function_code", "transaction_id", "client_port", "wall_time"):
        bad |= raw[col].isna()
    fc = raw["function_code"]
    reads = fc.isin(READ_FCS)
    writes = fc.isin(WRITE_SINGLE_FCS | WRITE_MULTI_FCS)
    bad |= (reads | writes) & (raw["address"].isna() | raw["count"].isna())
    blank_values = df["values"].isna() | (df["values"].astype(str).str.strip() == "")
    bad |= writes & blank_values
    bad |= df["value0"].isna()
    return bad


def load_requests(csv_path: str) -> pd.DataFrame:
    """Load a capture/labeled CSV and return only request frames, typed and
    time-sorted, with derived per-connection features."""
    # `values` must be read as text. A capture whose writes are all single
    # values (e.g. the normal-only training session, which never sends FC16)
    # would otherwise be parsed as numbers, and _first_value would turn every
    # written value into 0 - the model would train on writes it never sees.
    # raw_hex too: an all-digit hex column would otherwise become numbers.
    df = pd.read_csv(csv_path, dtype={"values": str, "raw_hex": str})
    df = df[df["direction"] == "req"].copy()

    # Numeric coercions; reads leave address/count/value blank -> 0. The
    # unfilled values are kept for the malformed check below.
    raw = {}
    for col in ["function_code", "address", "count", "transaction_id", "client_port"]:
        raw[col] = pd.to_numeric(df[col], errors="coerce")
        df[col] = raw[col].fillna(0).astype(int)
    df["value0"] = df["values"].apply(_first_value)
    df["wall_time"] = raw["wall_time"] = pd.to_numeric(df["wall_time"], errors="coerce")
    df["malformed"] = _malformed(df, raw)
    df["value0"] = df["value0"].fillna(0.0)
    if df["malformed"].any():
        print(f"[features] WARNING: {int(df['malformed'].sum())} request(s) in {csv_path} "
              "could not be fully decoded; kept and marked malformed", file=sys.stderr)

    # Many requests share a timestamp (the Windows clock ticks in steps), so
    # the sort must be stable: ties keep the file's order, which is the order
    # the tap saw them on the wire. Stateful features below depend on it.
    df = df.sort_values("wall_time", kind="stable").reset_index(drop=True)

    # A connection is (src_ip, client_port) when the capture has real hosts
    # (pcap_to_csv on the GRFICSv2 plant): ports can repeat across hosts. On
    # the single-host testbed every client is 127.0.0.1, so the port alone.
    if "src_ip" in df.columns:
        df["conn"] = df["src_ip"].astype(str) + ":" + df["client_port"].astype(str)
    else:
        df["conn"] = df["client_port"].astype(str)
        # Captures from before the tap logged the client IP are all from the
        # single-host loopback testbed, where every client was 127.0.0.1.
        df["src_ip"] = "127.0.0.1"
    df["src_ip"] = df["src_ip"].fillna("").astype(str)

    df["repeat_run"], df["write_step"] = _value_change(df)

    # Inter-arrival time within each TCP connection. The first request on a
    # connection has no predecessor -> 0, and is marked so the ML detector
    # can replace that placeholder, which is not a measured gap (left in, it
    # made each session's first request look unusual).
    df["inter_arrival"] = (
        df.groupby("conn")["wall_time"].diff().fillna(0.0)
    )
    df["first_on_connection"] = df.groupby("conn").cumcount() == 0
    # Change in transaction ID on the same connection (first request -> 1,
    # i.e. treated as a normal increment).
    df["txid_delta"] = (
        df.groupby("conn")["transaction_id"].diff().fillna(1.0)
    )

    if "is_attack" in df.columns:
        # A blank is_attack marks a request the detectors still see (it is part
        # of the traffic stream, e.g. the replay's seed packet) but that is
        # not graded. `scored` keeps that distinction once blanks become 0.
        is_attack = pd.to_numeric(df["is_attack"], errors="coerce")
        typo = is_attack.isna() & df["is_attack"].notna()
        if typo.any():
            raise ValueError(f"{csv_path}: {int(typo.sum())} is_attack value(s) are "
                             "neither blank nor a number")
        df["scored"] = is_attack.notna()
        df["is_attack"] = is_attack.fillna(0).astype(int)

    return df


def build_feature_matrix(df: pd.DataFrame, columns=None) -> np.ndarray:
    """Numeric feature matrix (rows = requests) for an ML detector."""
    return df[columns or ML_FEATURE_COLUMNS].to_numpy(dtype=float)
